import type { Difficulty, KeyPoint, Question, QuestionType, RoleId } from "../types";

// Seeded question bank. Answer keys and explanations are authored by hand;
// SQL solutions are executed against lib/cp/content/sqlData.ts.

const ALL: RoleId[] = ["ba", "pm", "marketing", "finance", "consulting", "software"];
const E: Difficulty = "Easy";
const M: Difficulty = "Medium";
const H: Difficulty = "Hard";

function mcq(
  id: string, roles: RoleId[], topic: string, difficulty: Difficulty, prompt: string,
  options: string[], answer: number, explanation: string, moduleId?: string
): Question {
  return { id, roles, topic, difficulty, type: "mcq", prompt, options, answer, explanation, moduleId };
}
function sql(
  id: string, roles: RoleId[], topic: string, difficulty: Difficulty, prompt: string,
  solution: string, explanation: string, orderMatters = false
): Question {
  return { id, roles, topic, difficulty, type: "sql", prompt, solution, explanation, orderMatters };
}
function written(
  id: string, type: QuestionType, roles: RoleId[], topic: string, difficulty: Difficulty, prompt: string,
  modelAnswer: string, keyPoints: KeyPoint[], explanation: string
): Question {
  return { id, roles, topic, difficulty, type, prompt, modelAnswer, keyPoints, explanation };
}
const kp = (label: string, ...any: string[]): KeyPoint => ({ label, any });

