export const QUESTION_MAP: Record<string, Question> = Object.fromEntries(QUESTIONS.map((q) => [q.id, q]));

export function questionsForModule(moduleId: string): Question[] {
  return QUESTIONS.filter((q) => q.moduleId === moduleId && q.type === "mcq");
}

export const TYPE_LABEL: Record<QuestionType, string> = {
  mcq: "Multiple choice",
  sql: "SQL",
  short: "Short answer",
  case: "Case",
  interview: "Interview question",
};
